assert(not game:GetService('RunService'):IsRunning(),'Stop Play before installing')
local rows=game.HttpService:JSONDecode([====[[{"path": ["ReplicatedStorage", "Shared", "MeteorShowerEffects"], "source": "-- Client-rendered, server-clock meteor choreography. Never excavates authored floors.\nlocal RunService = game:GetService(\"RunService\")\nlocal Players = game:GetService(\"Players\")\nlocal Effects = {}\nlocal STEP = 0.48\nlocal BIG_INTERVAL = 14\nlocal FIRST_BIG = 5\nlocal BIG_FLIGHT = 2.25\nlocal IMPACT_LIFETIME = 30\nlocal MAX_METEORS = 18\nlocal BIOMES = {\"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\", \"AncientRuins\", \"MagicalForest\", \"Sky\", \"Prehistoric\", \"Mythical\"}\n\nlocal function part(parent, name, size, cf, tint, material, alpha)\n local p = Instance.new(\"Part\")\n p.Name = name; p.Size = size; p.CFrame = cf; p.Color = tint\n p.Material = material or Enum.Material.Neon; p.Transparency = alpha or 0\n p.Anchored = true; p.CanCollide = false; p.CanTouch = false; p.CanQuery = false; p.CastShadow = false\n p.TopSurface = Enum.SurfaceType.Smooth; p.BottomSurface = Enum.SurfaceType.Smooth\n p.Parent = parent\n return p\nend\n\nlocal function emitter(parent, name, tint, size, life, speed)\n local e = Instance.new(\"ParticleEmitter\")\n e.Name = name; e.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n e.Color = ColorSequence.new(tint); e.LightEmission = 0.85; e.LightInfluence = 0\n e.Size = NumberSequence.new({NumberSequenceKeypoint.new(0, size), NumberSequenceKeypoint.new(1, 0)})\n e.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.1), NumberSequenceKeypoint.new(1, 1)})\n e.Lifetime = NumberRange.new(life * 0.65, life); e.Speed = NumberRange.new(speed * 0.5, speed)\n e.SpreadAngle = Vector2.new(180, 180); e.Rate = 0; e.Parent = parent\n return e\nend\n\nfunction Effects.Start(runtime, startedAt, isCurrent)\n local folder = Instance.new(\"Folder\"); folder.Name = \"MeteorShowerEffects\"; folder.Parent = runtime\n folder:SetAttribute(\"ImpactLifetime\", IMPACT_LIFETIME); folder:SetAttribute(\"LargeStrikeInterval\", BIG_INTERVAL)\n local ground = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\") or workspace:FindFirstChild(\"GrassFloor\")\n if ground and not ground:IsA(\"BasePart\") then ground = nil end\n local center = ground and ground.Position or Vector3.new(-338, 8, 248)\n local extent = ground and ground.Size * 0.5 or Vector3.new(650, 0, 650)\n local seed = math.floor(startedAt * 1000) % 2147483647\n local flights, impacts, flashes = {}, {}, {}\n local live, connection, destroying = true, nil, nil\n local lastSmall, lastBig = -1, -1\n local function randomFor(index, salt)\n  return Random.new((seed + index * 104729 + salt) % 2147483647)\n end\n local function active() return live and runtime.Parent ~= nil and isCurrent() end\n local function cleanup()\n  if not live then return end\n  live = false\n  if connection then connection:Disconnect() end\n  if destroying then destroying:Disconnect() end\n  table.clear(flights); table.clear(impacts); table.clear(flashes)\n  folder:Destroy()\n end\n destroying = runtime.Destroying:Connect(cleanup)\n\n local function launch(index, big, start, finish, launchAt, duration, size)\n  if #flights >= MAX_METEORS then return end\n  local meteor = part(folder, big and \"LargeMeteor\" or \"Meteor\", Vector3.one * size,\n   CFrame.lookAt(start, finish), Color3.fromRGB(255, 158, 65), Enum.Material.Neon)\n  meteor.Shape = Enum.PartType.Ball\n  meteor:SetAttribute(\"LaunchAt\", launchAt); meteor:SetAttribute(\"StrikeIndex\", index)\n  meteor:SetAttribute(\"StartPosition\", start); meteor:SetAttribute(\"TargetPosition\", finish)\n  local a = Instance.new(\"Attachment\"); a.Position = Vector3.new(-size * 0.35, 0, 0); a.Parent = meteor\n  local b = Instance.new(\"Attachment\"); b.Position = Vector3.new(size * 0.35, 0, 0); b.Parent = meteor\n  local trail = Instance.new(\"Trail\"); trail.Name = \"FireTrail\"; trail.Attachment0 = a; trail.Attachment1 = b\n  trail.Color = ColorSequence.new(Color3.fromRGB(255, 231, 166), Color3.fromRGB(255, 71, 26))\n  trail.Transparency = NumberSequence.new({NumberSequenceKeypoint.new(0, 0.05), NumberSequenceKeypoint.new(1, 1)})\n  trail.Lifetime = big and 0.9 or 0.55; trail.MinLength = 0.1; trail.LightEmission = 1; trail.FaceCamera = true; trail.Parent = meteor\n  local fire = emitter(meteor, \"FireSparks\", Color3.fromRGB(255, 131, 44), big and 5 or 1.5, 0.6, big and 12 or 4)\n  fire.Rate = big and 65 or 10\n  if big then\n   local rock = part(meteor, \"RockCore\", Vector3.one * (size * 0.74), meteor.CFrame, Color3.fromRGB(59, 39, 31), Enum.Material.Slate)\n   rock.Shape = Enum.PartType.Ball\n   local sound = Instance.new(\"Sound\"); sound.Name = \"MeteorWhoosh\"; sound.SoundId = \"rbxassetid://9120705982\"\n   sound.Volume = 0.35; sound.RollOffMinDistance = 40; sound.RollOffMaxDistance = 650; sound.Parent = meteor; sound:Play()\n   local light = Instance.new(\"PointLight\"); light.Color = Color3.fromRGB(255, 133, 63); light.Range = 45; light.Brightness = 2; light.Parent = meteor\n  end\n  table.insert(flights, {part = meteor, start = start, finish = finish, launchAt = launchAt, duration = duration, big = big})\n end\n\n local function impactTarget(index)\n  local random = randomFor(index, 9187)\n  local surfaces = {}\n  if ground then table.insert(surfaces, ground) end\n  for _,id in ipairs(BIOMES) do\n   local model = workspace:FindFirstChild(id)\n   local floor = model and model:FindFirstChild(id .. \"Floor\")\n   if floor and floor:IsA(\"BasePart\") then table.insert(surfaces, floor) end\n  end\n  if #surfaces == 0 then table.insert(surfaces, workspace.Terrain) end\n  local query = RaycastParams.new(); query.FilterType = Enum.RaycastFilterType.Include; query.FilterDescendantsInstances = surfaces; query.RespectCanCollide = true\n  local clear = RaycastParams.new(); clear.FilterType = Enum.RaycastFilterType.Exclude; clear.RespectCanCollide = true\n  local exclude = {runtime}\n  for _,player in ipairs(Players:GetPlayers()) do if player.Character then table.insert(exclude, player.Character) end end\n  clear.FilterDescendantsInstances = exclude\n  for _ = 1, 12 do\n   local pos = center + Vector3.new(random:NextNumber(-math.max(0, extent.X - 50), math.max(0, extent.X - 50)), 1200, random:NextNumber(-math.max(0, extent.Z - 50), math.max(0, extent.Z - 50)))\n   local hit = workspace:Raycast(pos, Vector3.new(0, -2400, 0), query)\n   if hit and hit.Normal.Y > 0.95 then\n    local open = true\n    -- Leave buildings/tree trunks alone and keep every crater rim on real support.\n    for _,offset in ipairs({Vector3.zero, Vector3.new(16, 0, 0), Vector3.new(-16, 0, 0), Vector3.new(0, 0, 16), Vector3.new(0, 0, -16)}) do\n     local down = workspace:Raycast(hit.Position + offset + Vector3.new(0, 150, 0), Vector3.new(0, -154, 0), clear)\n     if not down or not table.find(surfaces, down.Instance) or math.abs(down.Position.Y - hit.Position.Y) > 1 then open = false; break end\n    end\n    if open then return hit.Position end\n   end\n  end\n  return nil -- skip a blocked strike rather than damage a structure\n end\n\n local function makeImpact(index, position, impactAt, now)\n  if now >= impactAt + IMPACT_LIFETIME then return end\n  local random = randomFor(index, 4701)\n  local model = Instance.new(\"Model\"); model.Name = \"MeteorImpact\"\n  model:SetAttribute(\"ImpactAt\", impactAt); model:SetAttribute(\"ExpiresAt\", impactAt + IMPACT_LIFETIME)\n  model:SetAttribute(\"StrikeIndex\", index); model:SetAttribute(\"WorldPosition\", position); model.Parent = folder\n  local surface = position.Y + 0.045\n  local scorch = part(model, \"ScorchedGround\", Vector3.new(0.08, 28, 28), CFrame.new(position.X, surface, position.Z) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(31, 28, 30), Enum.Material.Slate, 0.1)\n  scorch.Shape = Enum.PartType.Cylinder\n  local molten = part(model, \"CoolingImpact\", Vector3.new(0.09, 12, 12), CFrame.new(position.X, surface + 0.06, position.Z) * CFrame.Angles(0, 0, math.pi / 2), Color3.fromRGB(255, 99, 27), Enum.Material.Neon, 0.1)\n  molten.Shape = Enum.PartType.Cylinder\n  for i = 1, 12 do\n   local angle = i / 12 * math.pi * 2\n   local radius = random:NextNumber(11.7, 13.2)\n   local height = random:NextNumber(1.2, 2.7)\n   part(model, \"CraterRubble\", Vector3.new(random:NextNumber(3, 5), height, random:NextNumber(2, 4)), CFrame.new(position + Vector3.new(math.cos(angle) * radius, height * 0.5 + 0.04, math.sin(angle) * radius)) * CFrame.Angles(0, -angle, 0), Color3.fromRGB(70, 59, 54), Enum.Material.Slate)\n   if i % 2 == 0 then\n    local length = random:NextNumber(5, 9)\n    part(model, \"GroundCrack\", Vector3.new(length, 0.065, 0.32), CFrame.new(position + Vector3.new(math.cos(angle) * 7, 0.13, math.sin(angle) * 7)) * CFrame.Angles(0, -angle, 0), Color3.fromRGB(246, 102, 32), Enum.Material.Neon, 0.1)\n   end\n  end\n  local smoke = emitter(scorch, \"ImpactEmbers\", Color3.fromRGB(255, 139, 60), 0.55, 2, 7)\n  smoke.Acceleration = Vector3.new(0, 6, 0); smoke.Rate = 12\n  if now - impactAt < 0.6 then\n   local burst = part(folder, \"ImpactFlash\", Vector3.one * 7, CFrame.new(position + Vector3.new(0, 2, 0)), Color3.fromRGB(255, 187, 80), Enum.Material.Neon, 0.2)\n   burst.Shape = Enum.PartType.Ball\n   table.insert(flashes, {part = burst, at = now})\n   smoke:Emit(65)\n   local sound = Instance.new(\"Sound\"); sound.Name = \"MeteorImpactSound\"; sound.SoundId = \"rbxassetid://12222030\"\n   sound.Volume = 0.38; sound.PlaybackSpeed = 0.85; sound.RollOffMinDistance = 35; sound.RollOffMaxDistance = 500; sound.Parent = scorch; sound:Play()\n   local dust = emitter(scorch, \"ImpactDust\", Color3.fromRGB(167, 139, 112), 3, 1.2, 34)\n   dust.Texture = \"rbxasset://textures/particles/smoke_main.dds\"; dust.Acceleration = Vector3.new(0, -12, 0); dust:Emit(35)\n  end\n  local parts = {}\n  for _,p in ipairs(model:GetChildren()) do if p:IsA(\"BasePart\") then table.insert(parts, {part = p, alpha = p.Transparency}) end end\n  table.insert(impacts, {model = model, at = impactAt, parts = parts, smoke = smoke, molten = molten})\n end\n\n local function small(index)\n  local random = randomFor(index, 1201)\n  local at = startedAt + index * STEP\n  for lane = 1, 2 do\n   local aim = center + Vector3.new(random:NextNumber(-extent.X * 0.8, extent.X * 0.8), random:NextNumber(110, 280), random:NextNumber(-extent.Z * 0.8, extent.Z * 0.8))\n   local direction = Vector3.new(random:NextNumber(430, 850), -random:NextNumber(65, 150), random:NextNumber(-260, 260))\n   launch(index * 2 + lane, false, aim - direction * 0.5, aim + direction * 0.5, at, random:NextNumber(0.8, 1.3), random:NextNumber(3.5, 7))\n  end\n end\n local function big(index, now)\n  local at = startedAt + FIRST_BIG + index * BIG_INTERVAL\n  local position = impactTarget(index)\n  if not position then return end\n  local impactAt = at + BIG_FLIGHT\n  if now < impactAt then\n   local random = randomFor(index, 8039)\n   local start = position + Vector3.new(-random:NextNumber(230, 420), 570, random:NextNumber(-170, 170))\n   launch(index, true, start, position + Vector3.new(0, 5, 0), at, BIG_FLIGHT, 13)\n  else makeImpact(index, position, impactAt, now) end\n end\n local accumulator = 0\n local function update()\n  if not active() then cleanup(); return end\n  local now = workspace:GetServerTimeNow()\n  local elapsed = math.max(0, now - startedAt)\n  local smallIndex = math.floor(elapsed / STEP)\n  if smallIndex > lastSmall then\n   -- Reconstruct only still-visible flight slots after a late join/frame stall.\n   for index = math.max(lastSmall + 1, smallIndex - 2), smallIndex do small(index) end\n   lastSmall = smallIndex\n  end\n  local bigIndex = math.floor((elapsed - FIRST_BIG) / BIG_INTERVAL)\n  if bigIndex > lastBig then\n   for index = math.max(lastBig + 1, math.ceil((elapsed - FIRST_BIG - BIG_FLIGHT - IMPACT_LIFETIME) / BIG_INTERVAL), 0), bigIndex do big(index, now) end\n   lastBig = bigIndex\n  end\n  for i = #flights, 1, -1 do\n   local flight = flights[i]\n   local alpha = math.clamp((now - flight.launchAt) / flight.duration, 0, 1)\n   if alpha >= 1 then\n    if flight.big then makeImpact(flight.part:GetAttribute(\"StrikeIndex\"), flight.finish - Vector3.new(0, 5, 0), flight.launchAt + flight.duration, now) end\n    flight.part:Destroy(); table.remove(flights, i)\n   else\n    local p = flight.start:Lerp(flight.finish, alpha)\n    flight.part.CFrame = CFrame.lookAt(p, flight.finish)\n    local core = flight.part:FindFirstChild(\"RockCore\")\n    if core then core.CFrame = flight.part.CFrame * CFrame.Angles(alpha * 8, alpha * 6, alpha * 3) end\n   end\n  end\n  for i = #impacts, 1, -1 do\n   local impact = impacts[i]; local age = now - impact.at\n   if age >= IMPACT_LIFETIME then impact.model:Destroy(); table.remove(impacts, i)\n   else\n    local fade = math.clamp((age - 26) / 4, 0, 1)\n    for _,entry in ipairs(impact.parts) do entry.part.Transparency = entry.alpha + (1 - entry.alpha) * fade end\n    impact.molten.Transparency = math.max(impact.molten.Transparency, math.clamp(age / 12, 0.1, 1))\n    impact.smoke.Enabled = age < 9\n   end\n  end\n  for i = #flashes, 1, -1 do\n   local flash = flashes[i]; local alpha = (now - flash.at) / 0.65\n   if alpha >= 1 then flash.part:Destroy(); table.remove(flashes, i)\n   else flash.part.Size = Vector3.one * (7 + 36 * alpha); flash.part.Transparency = 0.2 + alpha * 0.8 end\n  end\n end\n update()\n if live then\n  connection = RunService.Heartbeat:Connect(function(dt) accumulator += dt; if accumulator >= 1/30 then accumulator = 0; update() end end)\n end\n return cleanup\nend\n\nreturn Effects\n", "class": "ModuleScript"}, {"path": ["ReplicatedStorage", "Shared", "SpiritNightEffects"], "source": "-- Client-only, cosmetic visitors for Spirit Night. Ghost paths belong to the\n-- world; the viewer position only chooses which nearby paths are rendered.\n-- Every client evaluates the same path from the authoritative event start.\nlocal Players = game:GetService(\"Players\")\nlocal RunService = game:GetService(\"RunService\")\n\nlocal SpiritNightEffects = {}\nlocal MAX_GHOSTS = 12\nlocal UPDATE_STEP = 1 / 30\nlocal SELECTION_STEP = 2\nlocal PARTICLES_PER_GHOST = 11 -- 132/s maximum, plus the existing weather mist.\nlocal BIOMES = {\n\t\"Meadow\", \"Forest\", \"Jungle\", \"Desert\", \"Snow\", \"Volcano\", \"Ocean\",\n\t\"AncientRuins\", \"MagicalForest\", \"Sky\", \"Prehistoric\", \"Mythical\",\n}\n\nlocal function viewerPosition()\n\tlocal player = Players.LocalPlayer\n\tlocal character = player and player.Character\n\tlocal root = character and character:FindFirstChild(\"HumanoidRootPart\")\n\tif root then return root.Position end\n\tlocal camera = workspace.CurrentCamera\n\treturn camera and camera.CFrame.Position or Vector3.new(-338, 15, 248)\nend\n\nlocal function part(model, name, size, offset, tint, transparency, material)\n\tlocal value = Instance.new(\"Part\")\n\tvalue.Name = name\n\tvalue.Shape = Enum.PartType.Ball\n\tvalue.Size = size\n\tvalue.CFrame = offset\n\tvalue.Color = tint\n\tvalue.Material = material or Enum.Material.Neon\n\tvalue.Transparency = transparency\n\tvalue.Anchored = true\n\tvalue.CanCollide = false\n\tvalue.CanTouch = false\n\tvalue.CanQuery = false\n\tvalue.CastShadow = false\n\tvalue.Parent = model\n\treturn value\nend\n\nlocal function emitter(parent, name, rate, smoke, tint)\n\tlocal value = Instance.new(\"ParticleEmitter\")\n\tvalue.Name = name\n\tvalue.Texture = smoke and \"rbxasset://textures/particles/smoke_main.dds\"\n\t\tor \"rbxasset://textures/particles/sparkles_main.dds\"\n\tvalue.Rate = rate\n\tvalue.Lifetime = smoke and NumberRange.new(1.4, 2.2) or NumberRange.new(2, 3.2)\n\tvalue.Speed = smoke and NumberRange.new(0.4, 1.1) or NumberRange.new(1.2, 3)\n\tvalue.Acceleration = Vector3.new(0, smoke and 0.7 or 1.4, 0)\n\tvalue.SpreadAngle = Vector2.new(160, 160)\n\tvalue.Rotation = NumberRange.new(0, 360)\n\tvalue.RotSpeed = NumberRange.new(-35, 35)\n\tvalue.LightEmission = 0.8\n\tvalue.LightInfluence = 0\n\tvalue.LockedToPart = false\n\tvalue.Color = ColorSequence.new(tint, Color3.fromRGB(177, 144, 255))\n\tvalue.Size = smoke and NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 1.3),\n\t\tNumberSequenceKeypoint.new(1, 4),\n\t}) or NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 0),\n\t\tNumberSequenceKeypoint.new(0.2, 0.24),\n\t\tNumberSequenceKeypoint.new(1, 0),\n\t})\n\tvalue.Transparency = NumberSequence.new({\n\t\tNumberSequenceKeypoint.new(0, 1),\n\t\tNumberSequenceKeypoint.new(0.2, smoke and 0.78 or 0.16),\n\t\tNumberSequenceKeypoint.new(0.7, smoke and 0.9 or 0.4),\n\t\tNumberSequenceKeypoint.new(1, 1),\n\t})\n\tvalue.Parent = parent\n\treturn value\nend\n\nlocal function worldPaths(startedAt)\n\tlocal paths = {}\n\tlocal ground = workspace:FindFirstChild(\"AnimalKingdomConcreteGround\")\n\tlocal supports = {}\n\tif ground and ground:IsA(\"BasePart\") then table.insert(supports, ground) end\n\tlocal town = workspace:FindFirstChild(\"TownPlaza\")\n\tif town and town:IsA(\"BasePart\") then table.insert(supports, town) end\n\tfor _, name in ipairs(BIOMES) do\n\t\tlocal biome = workspace:FindFirstChild(name)\n\t\tlocal floor = biome and biome:FindFirstChild(name .. \"Floor\")\n\t\tif floor and floor:IsA(\"BasePart\") then table.insert(supports, floor) end\n\tend\n\t-- The source-only development map has a different footprint from the\n\t-- authored place. Use its actual floor rather than spawning off the map.\n\tif #supports == 0 then\n\t\tlocal floor = workspace:FindFirstChild(\"GrassFloor\")\n\t\tif floor and floor:IsA(\"BasePart\") then\n\t\t\tground = floor\n\t\t\ttable.insert(supports, floor)\n\t\tend\n\tend\n\tif #supports == 0 then return paths end\n\tground = ground or supports[1]\n\tlocal ray = RaycastParams.new()\n\tray.FilterType = Enum.RaycastFilterType.Include\n\tray.FilterDescendantsInstances = supports\n\tray.IgnoreWater = true\n\tlocal seed = math.floor(startedAt * 1000) % 2147483647\n\tlocal random = Random.new(seed)\n\tlocal halfX = math.max(0, ground.Size.X * 0.5 - 55)\n\tlocal halfZ = math.max(0, ground.Size.Z * 0.5 - 55)\n\t-- A fixed 85-stud lattice keeps paths available across Town, plots, and\n\t-- every biome without scanning Workspace or creating a whole-map crowd.\n\tfor x = -halfX, halfX, 85 do\n\t\tfor z = -halfZ, halfZ, 85 do\n\t\t\tlocal world = ground.CFrame:PointToWorldSpace(Vector3.new(x, 0, z))\n\t\t\tlocal hit = workspace:Raycast(world + Vector3.new(0, 300, 0), Vector3.new(0, -600, 0), ray)\n\t\t\tif hit then\n\t\t\t\ttable.insert(paths, {\n\t\t\t\t\tid = #paths + 1,\n\t\t\t\t\tcenter = hit.Position + Vector3.new(0, random:NextNumber(6, 10), 0),\n\t\t\t\t\tradius = random:NextNumber(8, 17),\n\t\t\t\t\tphase = random:NextNumber(0, math.pi * 2),\n\t\t\t\t\tspeed = random:NextNumber(0.14, 0.25),\n\t\t\t\t\tscale = random:NextNumber(1.1, 1.55),\n\t\t\t\t\ttint = Color3.fromRGB(random:NextInteger(162, 202), 245, 255),\n\t\t\t\t})\n\t\t\tend\n\t\tend\n\tend\n\treturn paths\nend\n\nlocal function makeGhost(folder, path, now)\n\tlocal model = Instance.new(\"Model\")\n\tmodel.Name = \"FloatingGhost_\" .. path.id\n\tmodel:SetAttribute(\"WorldPathCenter\", path.center)\n\tlocal scale = path.scale\n\tlocal parts = {}\n\tlocal function add(name, size, position, transparency, face)\n\t\tlocal value = part(model, name, size * scale, CFrame.new(position * scale),\n\t\t\tface and Color3.fromRGB(20, 35, 55) or path.tint,\n\t\t\ttransparency, face and Enum.Material.SmoothPlastic or Enum.Material.Neon)\n\t\ttable.insert(parts, { value = value, transparency = transparency })\n\t\treturn value\n\tend\n\tlocal body = add(\"SheetBody\", Vector3.new(2.25, 2.7, 1.65), Vector3.new(0, -0.15, 0), 0.3)\n\tadd(\"RoundHead\", Vector3.new(2.55, 2.25, 1.85), Vector3.new(0, 1.1, 0), 0.2)\n\tadd(\"LeftWisp\", Vector3.new(0.85, 1.65, 0.95), Vector3.new(-0.7, -1.55, 0.12), 0.4)\n\tadd(\"CenterWisp\", Vector3.new(0.9, 2, 1), Vector3.new(0, -1.65, 0.2), 0.4)\n\tadd(\"RightWisp\", Vector3.new(0.85, 1.65, 0.95), Vector3.new(0.7, -1.55, 0.12), 0.4)\n\tadd(\"LeftEye\", Vector3.new(0.3, 0.48, 0.18), Vector3.new(-0.48, 1.3, -0.88), 0.08, true)\n\tadd(\"RightEye\", Vector3.new(0.3, 0.48, 0.18), Vector3.new(0.48, 1.3, -0.88), 0.08, true)\n\tadd(\"LittleMouth\", Vector3.new(0.25, 0.34, 0.14), Vector3.new(0, 0.7, -0.92), 0.1, true)\n\tmodel.WorldPivot = CFrame.new()\n\temitter(body, \"SpiritWisps\", 5, true, path.tint)\n\tlocal sparkles = emitter(body, \"WanderingFireflies\", PARTICLES_PER_GHOST - 5, false, path.tint)\n\t-- Fade in after positioning; nothing flashes at the origin on creation.\n\tfor _, entry in ipairs(parts) do entry.value.Transparency = 1 end\n\tmodel:PivotTo(CFrame.new(path.center))\n\tmodel.Parent = folder\n\tsparkles:Emit(8)\n\treturn { model = model, path = path, parts = parts, bornAt = now, fading = true }\nend\n\nfunction SpiritNightEffects.Start(runtime, startedAt, isCurrent)\n\tlocal folder = Instance.new(\"Folder\")\n\tfolder.Name = \"SpiritNightWorld\"\n\tfolder:SetAttribute(\"GhostLimit\", MAX_GHOSTS)\n\tfolder:SetAttribute(\"MaximumParticleRate\", MAX_GHOSTS * PARTICLES_PER_GHOST)\n\tfolder.Parent = runtime\n\tlocal paths = worldPaths(startedAt)\n\tlocal ghosts = {}\n\tlocal heartbeat\n\tlocal destroying\n\tlocal stopped = false\n\tlocal elapsed = 0\n\tlocal selectionElapsed = SELECTION_STEP\n\n\tlocal function cleanup()\n\t\tif stopped then return end\n\t\tstopped = true\n\t\tif heartbeat then heartbeat:Disconnect() end\n\t\tif destroying then destroying:Disconnect() end\n\t\ttable.clear(ghosts)\n\t\tfolder:Destroy()\n\tend\n\n\tlocal function selectNearby(now)\n\t\tlocal viewer = viewerPosition()\n\t\tlocal ranked = {}\n\t\tfor _, path in ipairs(paths) do\n\t\t\t-- Hysteresis prevents churn when standing between two paths.\n\t\t\tlocal distance = (path.center - viewer).Magnitude\n\t\t\ttable.insert(ranked, { path = path, score = distance - (ghosts[path.id] and 18 or 0) })\n\t\tend\n\t\ttable.sort(ranked, function(a, b) return a.score < b.score end)\n\t\tlocal selected = {}\n\t\tfor i = 1, math.min(MAX_GHOSTS, #ranked) do\n\t\t\tif ranked[i].score < 340 then selected[ranked[i].path.id] = ranked[i].path end\n\t\tend\n\t\tfor id, ghost in pairs(ghosts) do\n\t\t\tif not selected[id] then\n\t\t\t\tghost.model:Destroy()\n\t\t\t\tghosts[id] = nil\n\t\t\tend\n\t\tend\n\t\tfor id, path in pairs(selected) do\n\t\t\tif not ghosts[id] then ghosts[id] = makeGhost(folder, path, now) end\n\t\tend\n\tend\n\n\tdestroying = runtime.Destroying:Connect(cleanup)\n\theartbeat = RunService.Heartbeat:Connect(function(delta)\n\t\tif stopped then return end\n\t\tif not runtime.Parent or not folder.Parent or not isCurrent() then\n\t\t\tcleanup()\n\t\t\treturn\n\t\tend\n\t\telapsed += delta\n\t\tselectionElapsed += delta\n\t\tif elapsed < UPDATE_STEP then return end\n\t\telapsed %= UPDATE_STEP\n\t\tlocal now = workspace:GetServerTimeNow()\n\t\tif selectionElapsed >= SELECTION_STEP then\n\t\t\tselectionElapsed = 0\n\t\t\tselectNearby(now)\n\t\tend\n\t\tlocal age = math.max(0, now - startedAt)\n\t\tfor _, ghost in pairs(ghosts) do\n\t\t\tlocal path = ghost.path\n\t\t\tlocal theta = path.phase + age * path.speed\n\t\t\tlocal position = path.center + Vector3.new(\n\t\t\t\tmath.cos(theta) * path.radius,\n\t\t\t\tmath.sin(age * 1.3 + path.phase) * 1.15,\n\t\t\t\tmath.sin(theta) * path.radius * 0.7)\n\t\t\tlocal direction = Vector3.new(-math.sin(theta), 0, math.cos(theta) * 0.7)\n\t\t\tghost.model:PivotTo(CFrame.lookAt(position, position + direction)\n\t\t\t\t* CFrame.Angles(0, 0, math.sin(age * 0.9 + path.phase) * 0.09))\n\t\t\tif ghost.fading then\n\t\t\t\tlocal alpha = math.clamp((now - ghost.bornAt) / 0.65, 0, 1)\n\t\t\t\tfor _, entry in ipairs(ghost.parts) do\n\t\t\t\t\tentry.value.Transparency = 1 - (1 - entry.transparency) * alpha\n\t\t\t\tend\n\t\t\t\tghost.fading = alpha < 1\n\t\t\tend\n\t\tend\n\tend)\n\treturn cleanup\nend\n\nreturn SpiritNightEffects\n", "class": "ModuleScript"}, {"path": ["StarterPlayer", "StarterPlayerScripts", "WeatherVisualController"], "source": "local ReplicatedStorage = game:GetService(\"ReplicatedStorage\")\nlocal Lighting = game:GetService(\"Lighting\")\nlocal RunService = game:GetService(\"RunService\")\nlocal SoundService = game:GetService(\"SoundService\")\nlocal TweenService = game:GetService(\"TweenService\")\n\nlocal DEBUG_VISUALS = RunService:IsStudio()\nlocal TRANSITION = 2\nif DEBUG_VISUALS then print(\"[WeatherVisuals] Script starting\") end\nlocal state = ReplicatedStorage:WaitForChild(\"WeatherState\")\nlocal shared = ReplicatedStorage:WaitForChild(\"Shared\")\nlocal definitions = require(shared:WaitForChild(\"EventDefinitions\"))\nlocal meteorShowerEffects = require(shared:WaitForChild(\"MeteorShowerEffects\"))\nlocal spiritNightEffects = require(shared:WaitForChild(\"SpiritNightEffects\"))\nlocal rng = Random.new()\n\nlocal function color(r, g, b)\n\treturn Color3.fromRGB(r, g, b)\nend\n\n-- Every event has its own lighting recipe. Particle and sky details are added below.\nlocal presets = {\n\tSunnySkies = { clock = 13, brightness = 3.2, exposure = 0.16, fog = 100000, atmosphere = 0.1, tint = color(255, 244, 215), saturation = 0.16, bloom = 0.22, rays = 0.11, clouds = 0.06 },\n\tRainyDay = { clock = 15, brightness = 1.35, exposure = -0.18, fog = 530, atmosphere = 0.47, tint = color(173, 198, 225), saturation = -0.18, bloom = 0.08, rays = 0, clouds = 0.92, particles = \"Rain\" },\n\tThunderstorm = { clock = 18, brightness = 0.75, exposure = -0.38, fog = 280, fogStart = 0, atmosphere = 0.63, tint = color(118, 145, 183), saturation = -0.32, bloom = 0.15, rays = 0, clouds = 1, particles = \"HeavyRain\", extraParticles = \"WindStreaks\", loop = \"Lightning\" },\n\tSnowfall = { clock = 11, brightness = 2.1, exposure = 0.02, fog = 440, fogStart = 0, atmosphere = 0.47, tint = color(188, 223, 255), saturation = -0.34, bloom = 0.26, rays = 0.02, clouds = 0.75, particles = \"Snow\" },\n\tFoggy = { clock = 10, brightness = 1.25, exposure = -0.15, fog = 105, fogStart = 0, atmosphere = 0.74, tint = color(167, 187, 203), saturation = -0.48, bloom = 0.03, blur = 2, rays = 0, clouds = 0.76 },\n\tWindy = { clock = 14, brightness = 2, exposure = -0.02, fog = 850, atmosphere = 0.32, tint = color(207, 226, 217), saturation = 0.02, bloom = 0.08, rays = 0.02, clouds = 0.8, particles = \"Leaves\", extraParticles = \"WindStreaks\", loop = \"Wind\" },\n\tHeatwave = { clock = 14, brightness = 3.35, exposure = 0.28, fog = 480, atmosphere = 0.4, tint = color(255, 206, 145), saturation = 0.19, bloom = 0.38, blur = 0.7, rays = 0.14, clouds = 0.04, particles = \"Haze\" },\n\tAurora = { clock = 0, brightness = 1.1, exposure = -0.12, fog = 100000, atmosphere = 0.15, tint = color(164, 196, 244), saturation = 0.32, bloom = 0.5, rays = 0, clouds = 0.08, particles = \"Stars\", sky = \"Aurora\" },\n\tBloodMoon = { clock = 0, brightness = 0.7, exposure = -0.3, fog = 100000, fogStart = 0, atmosphere = 0.2, tint = color(211, 89, 103), saturation = 0.05, bloom = 0.3, rays = 0, clouds = 0.52, particles = \"Ash\", sky = \"BloodMoon\" },\n\tMeteorShower = { clock = 0, brightness = 1.05, exposure = -0.12, fog = 100000, atmosphere = 0.16, tint = color(159, 180, 237), saturation = 0.2, bloom = 0.45, rays = 0, clouds = 0.03, particles = \"Stars\", loop = \"Meteors\" },\n\tSpiritNight = { clock = 1, brightness = 1.1, exposure = -0.1, fog = 650, atmosphere = 0.30, tint = color(134, 219, 235), saturation = 0.24, bloom = 0.44, rays = 0, clouds = 0.25, particles = \"SpiritMist\", loop = \"Spirits\" },\n\tRainbow = { clock = 14, brightness = 3.15, exposure = 0.16, fog = 100000, atmosphere = 0.06, tint = color(255, 240, 254), saturation = 0.4, bloom = 0.34, rays = 0.09, clouds = 0.12, particles = \"Sparkles\", sky = \"Rainbow\" },\n\tChaos = { clock = 19, brightness = 2, exposure = 0.04, fog = 410, atmosphere = 0.52, tint = color(255, 143, 209), saturation = 0.4, bloom = 0.5, rays = 0, clouds = 0.72, particles = \"Chaos\", loop = \"Chaos\" },\n\tInverted = { clock = 22, brightness = 1.55, exposure = 0.2, fog = 420, atmosphere = 0.55, tint = color(117, 250, 203), saturation = -0.38, bloom = 0.4, rays = 0, clouds = 0.6, particles = \"Inverted\" },\n\tNightmare = { clock = 0, brightness = 0.65, exposure = -0.39, fog = 240, atmosphere = 0.66, tint = color(166, 77, 127), saturation = -0.36, bloom = 0.25, rays = 0, clouds = 0.84, particles = \"Ash\", loop = \"Nightmare\" },\n\tVoid = { clock = 0, brightness = 0.65, exposure = -0.37, fog = 180, atmosphere = 0.69, tint = color(129, 85, 204), saturation = -0.18, bloom = 0.59, blur = 1.5, rays = 0, clouds = 0.86, particles = \"Void\", sky = \"Void\" },\n\tGolden = { clock = 16, brightness = 3.5, exposure = 0.3, fog = 1400, atmosphere = 0.22, tint = color(255, 204, 92), saturation = 0.31, bloom = 0.52, rays = 0.16, clouds = 0.1, particles = \"Gold\" },\n\tAdminAbuse = { clock = 17, brightness = 2.5, exposure = 0.09, fog = 520, atmosphere = 0.38, tint = color(255, 198, 247), saturation = 0.38, bloom = 0.52, rays = 0.06, clouds = 0.58, particles = \"Admin\", loop = \"Admin\" },\n}\n\n-- WeatherState uses the canonical IDs in EventDefinitions. Accept the older\n-- underscored spellings as input without changing the server's event contract.\nlocal aliases = {\n\tSunny_Skies = \"SunnySkies\", Rainy_Day = \"RainyDay\", Blood_Moon = \"BloodMoon\",\n\tMeteor_Shower = \"MeteorShower\", Spirit_Night = \"SpiritNight\", Admin_Abuse = \"AdminAbuse\",\n}\n\nlocal lightingProperties = { \"Brightness\", \"ClockTime\", \"ExposureCompensation\", \"FogStart\", \"FogEnd\", \"FogColor\", \"Ambient\", \"OutdoorAmbient\", \"ColorShift_Top\", \"ColorShift_Bottom\" }\nlocal effectProperties = {\n\tAtmosphere = { \"Density\", \"Color\", \"Decay\", \"Haze\", \"Glare\", \"Offset\" },\n\tClouds = { \"Cover\", \"Density\", \"Color\", \"Enabled\" },\n\tColorCorrectionEffect = { \"Brightness\", \"Contrast\", \"Saturation\", \"TintColor\", \"Enabled\" },\n\tBloomEffect = { \"Intensity\", \"Size\", \"Threshold\", \"Enabled\" },\n\tSunRaysEffect = { \"Intensity\", \"Spread\", \"Enabled\" },\n\tDepthOfFieldEffect = { \"FarIntensity\", \"FocusDistance\", \"InFocusRadius\", \"NearIntensity\", \"Enabled\" },\n\tBlurEffect = { \"Size\", \"Enabled\" },\n}\nlocal original = {}\nfor _, property in ipairs(lightingProperties) do original[property] = Lighting[property] end\n-- The folder is a client-local index of managed effects. Roblox renders\n-- Atmosphere/post effects under Lighting and Clouds under Terrain, so the live\n-- instances cannot be placed inside this folder without disabling them.\nlocal visualFolder = Lighting:FindFirstChild(\"AK_WeatherVisuals\")\nif not visualFolder then\n\tvisualFolder = Instance.new(\"Folder\")\n\tvisualFolder.Name = \"AK_WeatherVisuals\"\n\tvisualFolder.Parent = Lighting\nend\nlocal function indexEffect(className, effect)\n\tlocal reference = visualFolder:FindFirstChild(className)\n\tif not reference or not reference:IsA(\"ObjectValue\") then\n\t\treference = Instance.new(\"ObjectValue\")\n\t\treference.Name = className\n\t\treference.Parent = visualFolder\n\tend\n\treference.Value = effect\nend\nlocal effects = {}\nlocal initialEffects = {}\nlocal createdEffects = {}\nlocal terrain = workspace.Terrain\nlocal requiredEffects = { \"Atmosphere\", \"ColorCorrectionEffect\", \"BloomEffect\", \"BlurEffect\", \"SunRaysEffect\", \"Clouds\" }\nlocal effectLabels = {\n\tColorCorrectionEffect = \"ColorCorrection\", BloomEffect = \"Bloom\",\n\tBlurEffect = \"Blur\", SunRaysEffect = \"SunRays\",\n}\n\nlocal function ensureEffect(className, parent)\n\tlocal effect = effects[className]\n\tif effect and effect.Parent == parent then\n\t\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\t\treturn effect\n\tend\n\teffect = parent:FindFirstChildOfClass(className)\n\tif effect and not initialEffects[className] then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(effectProperties[className]) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\tcreatedEffects[className] = nil\n\tend\n\tif not effect then\n\t\tlocal ok, result = pcall(Instance.new, className)\n\t\tif not ok then\n\t\t\twarn(\"[WeatherVisuals] Cannot create \" .. className .. \": \" .. tostring(result))\n\t\t\treturn nil\n\t\tend\n\t\teffect = result\n\t\teffect.Name = \"AK_Weather\" .. className\n\t\tif effect:IsA(\"PostEffect\") then effect.Enabled = false end\n\t\tif className == \"Atmosphere\" then\n\t\t\teffect.Density = 0\n\t\t\teffect.Haze = 0\n\t\t\teffect.Glare = 0\n\t\telseif className == \"Clouds\" then\n\t\t\teffect.Cover = 0\n\t\t\teffect.Enabled = false\n\t\tend\n\t\teffect.Parent = parent\n\t\tcreatedEffects[className] = true\n\tend\n\teffects[className] = effect\n\tindexEffect(className, effect)\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] \" .. (effectLabels[className] or className) .. \" ready\") end\n\treturn effect\nend\n\n-- Capture the real map appearance before any weather instance is created.\nfor className, properties in pairs(effectProperties) do\n\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\tlocal effect = parent:FindFirstChildOfClass(className)\n\tif effect then\n\t\tlocal snapshot = {}\n\t\tfor _, property in ipairs(properties) do snapshot[property] = effect[property] end\n\t\tinitialEffects[className] = snapshot\n\t\teffects[className] = effect\n\t\tindexEffect(className, effect)\n\tend\nend\n\nlocal generation = 0\nlocal activeKey\nlocal activeEventId\nlocal runtime\nlocal followConnection\nlocal phenomenaCleanup\nlocal runningTweens = {}\nlocal refreshQueued = false\nlocal activeSounds = {}\nlocal skyMoonSnapshots = {}\n\n-- World coordinates shared by every client. Only the nearby precipitation\n-- volume follows camera POSITION; environmental sky objects never follow it.\nlocal WORLD_SKY = {\n\tBloodMoon = Vector3.new(-6338, 8008, -23752),\n\tRainbow = Vector3.new(-500, 60, -2200),\n\tAurora = Vector3.new(-500, 850, -1700),\n\tMeteors = Vector3.new(-338, 1508, -1952),\n\tLightning = Vector3.new(-338, 658, -852),\n\tVoid = Vector3.new(-338, 108, 18),\n}\n\n-- Creator Store audio. Only the rain and thunder tracks are Roblox-owned;\n-- the wind/meteor clips are free Creator Store sound effects.\nlocal soundAssets = {\n\tRain = \"rbxassetid://1516791621\",\n\tThunder = \"rbxassetid://12222030\",\n\tWind = \"rbxassetid://8202539690\",\n\tEerieWind = \"rbxassetid://9114228918\",\n\tMeteor = \"rbxassetid://9120705982\",\n}\nlocal ambientSounds = {\n\tRainyDay = { \"Rain\", 0.42 }, Thunderstorm = { \"Rain\", 0.62 },\n\tSnowfall = { \"Wind\", 0.2 }, Foggy = { \"EerieWind\", 0.16 },\n\tWindy = { \"Wind\", 0.5 }, BloodMoon = { \"EerieWind\", 0.25 },\n\tSpiritNight = { \"EerieWind\", 0.19 }, Nightmare = { \"EerieWind\", 0.3 },\n\tVoid = { \"EerieWind\", 0.3 }, Chaos = { \"EerieWind\", 0.22 },\n\tAdminAbuse = { \"Rain\", 0.24 },\n}\n\nlocal function trackTween(instance, properties, seconds)\n\tif not instance then\n\t\twarn(\"[WeatherVisuals] Cannot tween a missing visual instance\")\n\t\treturn nil\n\tend\n\tlocal ok, animation = pcall(TweenService.Create, TweenService, instance, TweenInfo.new(seconds or TRANSITION, Enum.EasingStyle.Sine, Enum.EasingDirection.InOut), properties)\n\tif not ok then\n\t\twarn(\"[WeatherVisuals] Tween failed for \" .. instance.Name .. \": \" .. tostring(animation))\n\t\t-- Keep the preset visible even if a property cannot be tweened in Studio.\n\t\tfor property, value in pairs(properties) do\n\t\t\tlocal setOk, setError = pcall(function() instance[property] = value end)\n\t\t\tif not setOk then warn(\"[WeatherVisuals] Cannot set \" .. instance.Name .. \".\" .. property .. \": \" .. tostring(setError)) end\n\t\tend\n\t\treturn nil\n\tend\n\ttable.insert(runningTweens, animation)\n\tanimation.Completed:Connect(function()\n\t\tlocal index = table.find(runningTweens, animation)\n\t\tif index then table.remove(runningTweens, index) end\n\tend)\n\tanimation:Play()\n\treturn animation\nend\n\nlocal function cancelTweens()\n\t-- Cancel may fire Completed synchronously; swap the list first so its\n\t-- removal callback cannot skip every other active tween.\n\tlocal oldTweens = runningTweens\n\trunningTweens = {}\n\tfor _, animation in ipairs(oldTweens) do animation:Cancel() end\nend\n\nlocal function playWeatherSound(kind, volume, looped)\n\tlocal sound = Instance.new(\"Sound\")\n\tsound.Name = \"AK_Weather\" .. kind\n\tsound.SoundId = soundAssets[kind]\n\tsound.Looped = looped\n\tsound.Volume = 0\n\tsound.Parent = SoundService\n\ttable.insert(activeSounds, sound)\n\tsound.Ended:Connect(function()\n\t\tlocal index = table.find(activeSounds, sound)\n\t\tif index then table.remove(activeSounds, index) end\n\t\tsound:Destroy()\n\tend)\n\tsound:Play()\n\ttrackTween(sound, { Volume = volume }, looped and 1.4 or 0.12)\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Audio: \" .. kind) end\n\ttask.delay(5, function()\n\t\tif DEBUG_VISUALS and sound.Parent and not sound.IsLoaded then\n\t\t\twarn(\"[WeatherVisuals] Audio not loaded: \" .. kind .. \" (check Creator Store access)\")\n\t\tend\n\tend)\n\tif not looped then\n\t\ttask.delay(6, function()\n\t\t\tlocal index = table.find(activeSounds, sound)\n\t\t\tif index then table.remove(activeSounds, index) end\n\t\t\tif sound.Parent then sound:Destroy() end\n\t\tend)\n\tend\n\treturn sound\nend\n\nlocal function fadeWeatherSounds()\n\tlocal oldSounds = activeSounds\n\tactiveSounds = {}\n\tfor _, sound in ipairs(oldSounds) do\n\t\tif sound.Parent then\n\t\t\ttrackTween(sound, { Volume = 0 }, 0.35)\n\t\ttask.delay(0.4, function() sound:Destroy() end)\n\t\tend\n\tend\nend\n\nlocal function restoreOriginal(token)\n\ttrackTween(Lighting, original)\n\tfor className, effect in pairs(effects) do\n\t\tlocal snapshot = initialEffects[className]\n\t\tif snapshot then\n\t\t\tlocal numericAndColor = {}\n\t\t\tfor property, value in pairs(snapshot) do\n\t\t\t\tif property ~= \"Enabled\" then numericAndColor[property] = value end\n\t\t\tend\n\t\t\ttrackTween(effect, numericAndColor)\n\t\t\tif snapshot.Enabled ~= nil then\n\t\t\t\ttask.delay(TRANSITION, function()\n\t\t\t\t\tif token == generation then effect.Enabled = snapshot.Enabled end\n\t\t\t\tend)\n\t\t\tend\n\t\telse\n\t\t\t-- Newly created effects fade to neutral, then leave Lighting entirely.\n\t\t\tif className == \"Atmosphere\" then trackTween(effect, { Density = 0, Haze = 0, Glare = 0 }) end\n\t\t\tif className == \"Clouds\" then trackTween(effect, { Cover = 0 }) end\n\t\t\tif className == \"ColorCorrectionEffect\" then trackTween(effect, { Brightness = 0, Contrast = 0, Saturation = 0, TintColor = Color3.new(1, 1, 1) }) end\n\t\t\tif className == \"BloomEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"SunRaysEffect\" then trackTween(effect, { Intensity = 0 }) end\n\t\t\tif className == \"BlurEffect\" then trackTween(effect, { Size = 0 }) end\n\t\tend\n\tend\n\ttask.delay(TRANSITION + 0.05, function()\n\t\tif token ~= generation then return end\n\t\tfor className in pairs(createdEffects) do\n\t\t\tlocal effect = effects[className]\n\t\t\tif effect then effect:Destroy() end\n\t\t\teffects[className] = nil\n\t\t\tindexEffect(className, nil)\n\t\tend\n\tend)\nend\n\nlocal function ensureEffects()\n\tlocal ready = true\n\tfor _, className in ipairs(requiredEffects) do\n\t\tlocal parent = className == \"Clouds\" and terrain or Lighting\n\t\tif not ensureEffect(className, parent) then ready = false end\n\tend\n\treturn ready\nend\n\nlocal function clearEvent(restore)\n\tgeneration += 1\n\tif phenomenaCleanup then phenomenaCleanup(); phenomenaCleanup = nil end\n\tcancelTweens()\n\tfadeWeatherSounds()\n\tif followConnection then followConnection:Disconnect(); followConnection = nil end\n\tif runtime then runtime:Destroy(); runtime = nil end\n\tfor sky, moonSize in pairs(skyMoonSnapshots) do\n\t\tif sky.Parent then sky.MoonAngularSize = moonSize end\n\tend\n\tskyMoonSnapshots = {}\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing previous effects\") end\n\tif DEBUG_VISUALS and activeEventId then print(\"[WeatherVisuals] Clearing \" .. activeEventId) end\n\tif DEBUG_VISUALS and restore and activeEventId then print(\"[WeatherVisuals] Restoring defaults\") end\n\tactiveKey = nil\n\tactiveEventId = nil\n\tif restore then restoreOriginal(generation) end\nend\n\nlocal function makePart(name, parent, size, tint, transparency)\n\tlocal part = Instance.new(\"Part\")\n\tpart.Name = name\n\tpart.Anchored = true\n\tpart.CanCollide = false\n\tpart.CanTouch = false\n\tpart.CanQuery = false\n\tpart.CastShadow = false\n\tpart.Material = Enum.Material.Neon\n\tpart.Color = tint\n\tpart.Transparency = transparency or 0\n\tpart.Size = size\n\tpart.Parent = parent\n\treturn part\nend\n\nlocal particleStyles = {\n\tRain = { rate = 380, speed = NumberRange.new(75, 95), life = NumberRange.new(0.7, 1), size = 0.35, squash = 2.5, color = color(192, 217, 247), spread = 7, acceleration = Vector3.new(3, -55, 0) },\n\tHeavyRain = { rate = 560, speed = NumberRange.new(95, 120), life = NumberRange.new(0.65, 0.95), size = 0.42, squash = 3, color = color(202, 224, 255), spread = 12, acceleration = Vector3.new(12, -75, 0) },\n\tSnow = { rate = 210, speed = NumberRange.new(14, 22), life = NumberRange.new(2.2, 3.4), size = 0.55, color = color(244, 250, 255), spread = 35, acceleration = Vector3.new(5, -4, 2) },\n\tLeaves = { rate = 95, speed = NumberRange.new(35, 55), life = NumberRange.new(1.1, 1.8), size = 0.43, color = color(167, 197, 105), spread = 20, direction = Enum.NormalId.Right, acceleration = Vector3.new(35, 1, 5) },\n\tWindStreaks = { rate = 105, speed = NumberRange.new(70, 105), life = NumberRange.new(0.55, 0.95), size = 0.38, squash = 2.8, color = color(212, 235, 246), spread = 12, direction = Enum.NormalId.Right, acceleration = Vector3.new(30, 0, 0) },\n\tHaze = { rate = 20, speed = NumberRange.new(2, 5), life = NumberRange.new(1.5, 2.5), size = 0.42, color = color(255, 201, 130), spread = 35, acceleration = Vector3.new(0, 3, 0) },\n\tStars = { rate = 22, speed = NumberRange.new(1, 3), life = NumberRange.new(1.5, 2.8), size = 0.18, color = color(185, 230, 255), spread = 55, acceleration = Vector3.new(0, 1, 0) },\n\tAsh = { rate = 24, speed = NumberRange.new(2, 5), life = NumberRange.new(2, 3), size = 0.2, color = color(202, 95, 119), spread = 55, acceleration = Vector3.new(1, 2, 0) },\n\tSpiritMist = { rate = 85, speed = NumberRange.new(2, 6), life = NumberRange.new(2.5, 4), size = 0.38, color = color(134, 241, 229), spread = 60, acceleration = Vector3.new(0, 3, 0) },\n\tSparkles = { rate = 42, speed = NumberRange.new(2, 7), life = NumberRange.new(1, 2), size = 0.18, color = color(255, 218, 244), spread = 70, acceleration = Vector3.new(0, 2, 0) },\n\tChaos = { rate = 35, speed = NumberRange.new(5, 13), life = NumberRange.new(1, 2), size = 0.2, color = color(255, 133, 211), spread = 90, acceleration = Vector3.new(0, 2, 0) },\n\tInverted = { rate = 32, speed = NumberRange.new(3, 8), life = NumberRange.new(1, 2), size = 0.2, color = color(122, 255, 211), spread = 70, acceleration = Vector3.new(0, 5, 0) },\n\tVoid = { rate = 43, speed = NumberRange.new(2, 6), life = NumberRange.new(2, 3), size = 0.3, color = color(162, 84, 255), spread = 75, acceleration = Vector3.new(0, 4, 0) },\n\tGold = { rate = 50, speed = NumberRange.new(3, 8), life = NumberRange.new(1.2, 2.2), size = 0.2, color = color(255, 213, 85), spread = 75, acceleration = Vector3.new(0, 2, 0) },\n\tAdmin = { rate = 55, speed = NumberRange.new(4, 12), life = NumberRange.new(1, 2), size = 0.22, color = color(255, 216, 104), spread = 80, acceleration = Vector3.new(0, 3, 0) },\n}\n\nlocal function addParticles(styleName, rig)\n\tlocal style = particleStyles[styleName]\n\tif not style then return end\n\tlocal emitter = Instance.new(\"ParticleEmitter\")\n\temitter.Name = styleName .. \"Particles\"\n\temitter.Texture = \"rbxasset://textures/particles/sparkles_main.dds\"\n\temitter.Shape = Enum.ParticleEmitterShape.Box\n\temitter.ShapeStyle = Enum.ParticleEmitterShapeStyle.Volume\n\temitter.EmissionDirection = style.direction or Enum.NormalId.Bottom\n\temitter.Rate = style.rate\n\temitter.Lifetime = style.life\n\temitter.Speed = style.speed\n\temitter.SpreadAngle = Vector2.new(style.spread, style.spread)\n\temitter.Acceleration = style.acceleration\n\temitter.Size = NumberSequence.new({ NumberSequenceKeypoint.new(0, style.size), NumberSequenceKeypoint.new(1, 0) })\n\tif style.squash then emitter.Squash = NumberSequence.new(style.squash) end\n\tif style.squash then emitter.Orientation = Enum.ParticleOrientation.VelocityParallel end\n\temitter.Transparency = NumberSequence.new({ NumberSequenceKeypoint.new(0, 0.08), NumberSequenceKeypoint.new(0.8, 0.22), NumberSequenceKeypoint.new(1, 1) })\n\temitter.Color = ColorSequence.new(style.color)\n\temitter.LightEmission = (styleName == \"Rain\" or styleName == \"HeavyRain\") and 0.08 or 0.55\n\temitter.LightInfluence = 0.15\n\temitter.Enabled = true\n\temitter.Parent = rig\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Created \" .. styleName .. \" effect; enabled=\" .. tostring(emitter.Enabled) .. \" rate=\" .. tostring(emitter.Rate)) end\nend\n\nlocal function skyAnchor(name, position)\n\tlocal anchor = makePart(name, runtime, Vector3.new(1, 1, 1), Color3.new(1, 1, 1), 1)\n\tanchor.Position = position\n\tanchor:SetAttribute(\"FixedWorldPosition\", position)\n\treturn anchor\nend\n\nlocal function attachment(parent, name, position, axis)\n\tlocal point = Instance.new(\"Attachment\")\n\tpoint.Name = name\n\tpoint.Position = position\n\tpoint.Axis = axis\n\tpoint.Parent = parent\n\treturn point\nend\n\nlocal function skyBeam(parent, name, from, to, tint, width, curve0, curve1)\n\tlocal beam = Instance.new(\"Beam\")\n\tbeam.Name = name\n\tbeam.Attachment0 = from\n\tbeam.Attachment1 = to\n\tbeam.Color = ColorSequence.new(tint)\n\tbeam.Width0 = width\n\tbeam.Width1 = width\n\tbeam.CurveSize0 = curve0\n\tbeam.CurveSize1 = curve1\n\tbeam.Segments = 32\n\tbeam.FaceCamera = true\n\tbeam.LightEmission = 1\n\tbeam.LightInfluence = 0\n\tbeam.Transparency = NumberSequence.new(0.26)\n\tbeam.Parent = parent\n\treturn beam\nend\n\nlocal function moonDisc(parent, name, size, position, tint, transparency)\n\tlocal disc = Instance.new(\"Frame\")\n\tdisc.Name = name\n\tdisc.AnchorPoint = Vector2.new(0.5, 0.5)\n\tdisc.Size = UDim2.fromScale(size, size)\n\tdisc.Position = position\n\tdisc.BackgroundColor3 = tint\n\tdisc.BackgroundTransparency = transparency or 0\n\tdisc.BorderSizePixel = 0\n\tdisc.Parent = parent\n\tlocal corner = Instance.new(\"UICorner\")\n\tcorner.CornerRadius = UDim.new(1, 0)\n\tcorner.Parent = disc\n\treturn disc\nend\n\nlocal function addSky(eventId)\n\tif eventId == \"Aurora\" then\n\t\tlocal anchor = skyAnchor(\"AuroraAnchor\", WORLD_SKY.Aurora)\n\t\tlocal auroraColors = { color(72, 255, 179), color(77, 228, 255), color(125, 164, 255), color(196, 117, 255), color(93, 255, 214) }\n\t\tfor index = 1, 5 do\n\t\t\tlocal from = attachment(anchor, \"RibbonStart\" .. index, Vector3.new(-750, index * 40, index * 80), Vector3.new(1, 1, 0).Unit)\n\t\t\tlocal to = attachment(anchor, \"RibbonEnd\" .. index, Vector3.new(750, index * 25, index * 80), Vector3.new(1, -1, 0).Unit)\n\t\t\tlocal ribbon = skyBeam(anchor, \"AuroraRibbon\", from, to, auroraColors[index], 55, 850, 850)\n\t\t\tribbon.Segments = 64\n\t\t\tribbon.Transparency = NumberSequence.new({\n\t\t\t\tNumberSequenceKeypoint.new(0, 1), NumberSequenceKeypoint.new(0.2, 0.26),\n\t\t\t\tNumberSequenceKeypoint.new(0.8, 0.26), NumberSequenceKeypoint.new(1, 1),\n\t\t\t})\n\t\tend\n\telseif eventId == \"BloodMoon\" then\n\t\tlocal anchor = skyAnchor(\"BloodMoonAnchor\", WORLD_SKY.BloodMoon)\n\t\t-- A world-space billboard remains at its anchored point and is occluded\n\t\t-- by buildings. Its scale is in STUDS, not fixed screen pixels.\n\t\tlocal moon = Instance.new(\"BillboardGui\")\n\t\tmoon.Name = \"BloodMoonDisc\"\n\t\tmoon.Adornee = anchor\n\t\tmoon.Size = UDim2.fromScale(1900, 1900)\n\t\tmoon.AlwaysOnTop = false\n\t\tmoon.LightInfluence = 0\n\t\tmoon.Brightness = 2\n\t\tmoon.MaxDistance = 0\n\t\tmoon.Parent = anchor\n\t\tmoonDisc(moon, \"Halo\", 1, UDim2.fromScale(0.5, 0.5), color(246, 60, 54), 0.83)\n\t\tlocal face = moonDisc(moon, \"MoonFace\", 0.88, UDim2.fromScale(0.5, 0.5), color(255, 118, 84))\n\t\tlocal gradient = Instance.new(\"UIGradient\")\n\t\tgradient.Color = ColorSequence.new(color(255, 186, 122), color(130, 24, 38))\n\t\tgradient.Rotation = 35\n\t\tgradient.Parent = face\n\t\tfor index, crater in ipairs({ {0.31, 0.35, 0.18}, {0.65, 0.30, 0.12}, {0.59, 0.64, 0.23}, {0.30, 0.65, 0.09}, {0.74, 0.50, 0.08} }) do\n\t\t\tmoonDisc(face, \"Crater\" .. index, crater[3], UDim2.fromScale(crater[1], crater[2]), color(108, 30, 37), 0.55)\n\t\tend\n\t\tfor _, sky in ipairs(Lighting:GetChildren()) do\n\t\t\tif sky:IsA(\"Sky\") then\n\t\t\t\tskyMoonSnapshots[sky] = sky.MoonAngularSize\n\t\t\t\tsky.MoonAngularSize = 0\n\t\t\tend\n\t\tend\n\telseif eventId == \"Rainbow\" then\n\t\tlocal anchor = skyAnchor(\"RainbowAnchor\", WORLD_SKY.Rainbow)\n\t\t-- Two cubic quarter-circle Beams per color make a smooth semicircle.\n\t\t-- The endpoints and arch stay fixed in the same world plane for everyone.\n\t\tlocal arcColors = { color(255, 90, 103), color(255, 177, 80), color(255, 237, 104), color(114, 227, 147), color(110, 188, 255), color(114, 123, 243), color(186, 132, 255) }\n\t\tfor index, tint in ipairs(arcColors) do\n\t\t\tlocal radius = 1204 - (index - 1) * 24.64\n\t\t\tlocal curve = radius * 0.5522847498\n\t\t\tlocal left = attachment(anchor, \"Left\" .. index, Vector3.new(-radius, 0, 0), Vector3.yAxis)\n\t\t\tlocal top = attachment(anchor, \"Top\" .. index, Vector3.new(0, radius, 0), Vector3.xAxis)\n\t\t\tlocal right = attachment(anchor, \"Right\" .. index, Vector3.new(radius, 0, 0), -Vector3.yAxis)\n\t\t\tfor _, beam in ipairs({\n\t\t\t\tskyBeam(anchor, \"RainbowArc\", left, top, tint, 24.08, curve, curve),\n\t\t\t\tskyBeam(anchor, \"RainbowArc\", top, right, tint, 24.08, curve, curve),\n\t\t\t}) do\n\t\t\t\tbeam.Segments = 64\n\t\t\t\tbeam.LightEmission = 0\n\t\t\t\tbeam.Transparency = NumberSequence.new(0.15)\n\t\t\tend\n\t\tend\n\telseif eventId == \"Void\" then\n\t\tlocal anchor = skyAnchor(\"VoidAnchor\", WORLD_SKY.Void)\n\t\tfor index = 1, 7 do\n\t\t\tlocal orb = makePart(\"VoidWisp\", anchor, Vector3.new(7, 7, 7), color(161, 77, 244), 0.32)\n\t\t\torb.Shape = Enum.PartType.Ball\n\t\t\torb.Position = WORLD_SKY.Void + Vector3.new((index - 4) * 55, math.sin(index) * 23, math.cos(index) * 30)\n\t\tend\n\tend\nend\n\nlocal function lightning(token, rig, preset)\n\tif token ~= generation or not runtime then return end\n\ttask.delay(rng:NextNumber(0.25, 0.55), function()\n\t\tif token == generation then playWeatherSound(\"Thunder\", 0.6, false) end\n\tend)\n\ttrackTween(Lighting, { ExposureCompensation = preset.exposure + 0.85 }, 0.07)\n\ttrackTween(effects.ColorCorrectionEffect, { Brightness = 0.24 }, 0.07)\n\ttask.delay(0.13, function()\n\t\tif token ~= generation then return end\n\t\ttrackTween(Lighting, { ExposureCompensation = preset.exposure }, 0.42)\n\t\ttrackTween(effects.ColorCorrectionEffect, { Brightness = 0 }, 0.42)\n\tend)\n\tlocal boltRoot = WORLD_SKY.Lightning + Vector3.new(rng:NextNumber(-700, 700), 0, rng:NextNumber(-300, 300))\n\tfor segment = 1, 3 do\n\t\tlocal bolt = makePart(\"DistantLightning\", runtime, Vector3.new(5, 120, 5), color(221, 239, 255), 0.08)\n\t\tbolt.CFrame = CFrame.new(boltRoot + Vector3.new((segment - 1) * 30, -(segment - 1) * 115, 0)) * CFrame.Angles(0, 0, math.rad(15))\n\t\ttrackTween(bolt, { Transparency = 1 }, 0.45)\n\t\ttask.delay(0.5, function() bolt:Destroy() end)\n\tend\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Lightning flash\") end\nend\n\nlocal function meteor(token, rig)\n\tif token ~= generation or not runtime then return end\n\tlocal count = 0\n\tfor _, child in ipairs(runtime:GetChildren()) do\n\t\tif child.Name == \"Meteor\" then count += 1 end\n\tend\n\tif count >= 8 then return end -- local quality cap\n\tif DEBUG_VISUALS then print(\"[WeatherVisuals] Creating meteor shower VFX\") end\n\tlocal startPosition = WORLD_SKY.Meteors + Vector3.new(rng:NextNumber(-1100, 300), rng:NextNumber(0, 450), rng:NextNumber(-600, 600))\n\tlocal endPosition = startPosition + Vector3.new(rng:NextNumber(700, 1300), -rng:NextNumber(480, 760), rng:NextNumber(120, 360))\n\tlocal diameter = rng:NextNumber(16, 26)\n\tlocal meteorPart = makePart(\"Meteor\", runtime, Vector3.new(diameter, diameter, diameter), color(255, 139, 62), 0.05)\n\tmeteorPart.Shape = Enum.PartType.Ball\n\tmeteorPart.CFrame = CFrame.lookAt(startPosition, endPosition)\n\tlocal fire = Instance.new(\"Fire\")\n\tfire.Size = math.min(30, diameter * 1.8)\n\tfire.Heat = 5\n\tfire.Color = color(255, 183, 76)\n\tfire.SecondaryColor = color(255, 75, 47)\n\tfire.Parent = meteorPart\n\tlocal glow = Instance.new(\"PointLight\")\n\tglow.Color = color(255, 129, 61)\n\tglow.Brightness = 2.5\n\tglow.Range = 24\n\tglow.Parent = meteorPart\n\tlocal trail = Instance.new(\"Trail\")\n\ttrail.Name = \"MeteorTrail\"\n\ttrail.Color = ColorSequence.new(color(255, 226, 151), color(255, 107, 74))\n\ttrail.Lifetime = 0.55\n\ttrail.MinLength = 0.1\n\tlocal a = Instance.new(\"Attachment\")\n\ta.Position = Vector3.new(0, 0, -diameter * 0.5)\n\ta.Parent = meteorPart\n\tlocal b = Instance.new(\"Attachment\")\n\tb.Position = Vector3.new(0, 0, diameter * 0.5)\n\tb.Parent = meteorPart\n\ttrail.Attachment0 = a\n\ttrail.Attachment1 = b\n\ttrail.Parent = meteorPart\n\ttrackTween(meteorPart, { Position = endPosition, Transparency = 0.25 }, 0.9)\n\ttask.delay(0.85, function()\n\t\tif token ~= generation or not rig.Parent then return end\n\t\tlocal burst = makePart(\"MeteorBurst\", runtime, Vector3.new(30, 30, 30), color(255, 169, 74), 0.18)\n\t\tburst.Shape = Enum.PartType.Ball\n\t\tburst.Position = endPosition\n\t\ttrackTween(burst, { Size = Vector3.new(110, 110, 110), Transparency = 1 }, 0.38)\n\t\ttask.delay(0.4, function() burst:Destroy() end)\n\tend)\n\ttask.delay(1, function() meteorPart:Destroy() end)\nend\n\nlocal function startLoop(kind, token, rig, preset)\n\tif not kind then return end\n\ttask.spawn(function()\n\t\tlocal step = 0\n\t\twhile token == generation and runtime do\n\t\t\tif kind == \"Lightning\" then\n\t\t\t\tlightning(token, rig, preset)\n\t\t\telseif kind == \"Wind\" then\n\t\t\t\tlocal gusts = rig:FindFirstChild(\"WindStreaksParticles\")\n\t\t\t\tif gusts then gusts:Emit(55) end\n\t\t\t\ttrackTween(effects.Clouds, { Cover = rng:NextNumber(0.58, 0.9) }, 2)\n\t\t\telseif kind == \"Chaos\" then\n\t\t\t\tstep += 1\n\t\t\t\ttrackTween(effects.ColorCorrectionEffect, { TintColor = Color3.fromHSV((step * 0.17) % 1, 0.46, 1), Saturation = 0.28 + (step % 2) * 0.15 }, 2)\n\t\t\t\ttrackTween(effects.Atmosphere, { Color = Color3.fromHSV((step * 0.13) % 1, 0.4, 1) }, 2)\n\t\t\t\tif step % 3 == 0 then lightning(token, rig, preset) end\n\t\t\telseif kind == \"Nightmare\" then\n\t\t\t\ttrackTween(effects.BloomEffect, { Intensity = step % 2 == 0 and 0.34 or preset.bloom }, 1.5)\n\t\t\t\tstep += 1\n\t\t\telseif kind == \"Admin\" then\n\t\t\t\tstep += 1\n\t\t\t\ttrackTween(effects.ColorCorrectionEffect, { TintColor = Color3.fromHSV((step * 0.12) % 1, 0.34, 1) }, 2)\n\t\t\t\tif step % 3 == 0 then lightning(token, rig, preset) end\n\t\t\t\tif step % 2 == 0 then meteor(token, rig) end\n\t\t\tend\n\t\t\tlocal pause = kind == \"Lightning\" and rng:NextNumber(4, 8)\n\t\t\t\tor kind == \"Wind\" and rng:NextNumber(2, 3.4)\n\t\t\t\tor 3\n\t\t\t-- Short waits let a replaced event stop promptly without another connection.\n\t\t\tlocal elapsed = 0\n\t\t\twhile elapsed < pause and token == generation do\n\t\t\t\telapsed += task.wait(math.min(0.25, pause - elapsed))\n\t\t\tend\n\t\tend\n\tend)\nend\n\nlocal function applyEvent(eventId, 